export type VnAdministrativeRegionType = 'BAC_BO' | 'TRUNG_BO' | 'TAY_NGUYEN' | 'NAM_BO';

export type VnHamletUnitType =
  | 'THON'
  | 'AP'
  | 'BAN'
  | 'LANG'
  | 'KHU_PHO'
  | 'TO_DAN_PHO'
  | 'KHOM'
  | 'TIEU_KHU'
  | 'XOM'
  | 'KHU_DO_THI'
  | 'DUONG_PHO';

export interface VnHamletUnitItem {
  code: string;
  name: string;
  unitType: VnHamletUnitType;
  aliases: string[];
  ghtkHamletName: string;
}

export interface VnWardUnitItem {
  code: string;
  name: string;
  unitType?: 'PHUONG' | 'XA' | 'THI_TRAN' | 'DAC_KHU';
  aliases: string[];
  ghnWardCode: string;
  ghtkWardName: string;
  vtpWardId?: number;
  /**
   * Đánh dấu Phường / Xã / Đặc khu mới được thành lập/sắp xếp theo 34 Nghị quyết của UBTVQH năm 2025 (Chinhphu.vn)
   * và Nghị quyết 202/2025/QH15 (mô hình chính quyền địa phương 3 cấp không tổ chức cấp huyện).
   */
  isNewPostMergerWard?: boolean;
  mergedFromWardNames?: string[];
  mergedIntoNewWardCode?: string;
  mergedIntoNewWardName?: string;
  legacyProvinceCode?: string;
  legacyProvinceName?: string;
  legacyDistrictCode?: string;
  legacyDistrictName?: string;
  mergedProvinceCode?: string;
  mergedProvinceName?: string;
  ghnProvinceId?: number;
  ghnDistrictId?: number;
  ghtkProvinceName?: string;
  ghtkDistrictName?: string;
  vtpProvinceId?: number;
  jtCityCode?: string;
  hamlets?: VnHamletUnitItem[];
}

export interface VnDistrictUnitItem {
  code: string;
  name: string;
  unitType?: 'QUAN' | 'HUYEN' | 'THI_XA' | 'THANH_PHO' | 'DAC_KHU';
  aliases: string[];
  ghnDistrictId: number;
  ghtkDistrictName: string;
  legacyProvinceCode?: string;
  legacyProvinceName?: string;
  mergedProvinceCode?: string;
  mergedProvinceName?: string;
  wards: VnWardUnitItem[];
}

export interface VnProvinceUnitItem {
  code: string;
  name: string;
  region?: VnAdministrativeRegionType;
  aliases: string[];
  ghnProvinceId: number;
  ghtkProvinceName: string;
  vtpProvinceId: number;
  jtCityCode: string;
  isCurrent34Province?: boolean;
  mergedIntoProvinceCode?: string;
  mergedIntoProvinceName?: string;
  mergedFromProvinceCodes?: string[];
  mergedFromProvinceNames?: string[];
  resolutionNumber?: string;
  ubtvqhResolutionNumber?: string;
  adminCenterName?: string;
  totalPostMergerCommunesCount?: number;
  /**
   * Danh sách đầy đủ các Phường / Xã / Đặc khu trực thuộc thẳng Tỉnh/Thành phố (KHÔNG CÓ CẤP HUYỆN)
   * dùng cho Tab 3 Cấp Hành Chính (34 Tỉnh/Thành mới theo Nghị quyết 202/2025/QH15 & 34 Nghị quyết UBTVQH năm 2025, Chinhphu.vn).
   * Tuyệt đối chỉ gồm Phường, Xã, Đặc khu (0 Thị trấn, 0 Phường đánh số cũ đã giải thể).
   */
  directWards?: VnWardUnitItem[];
  districts: VnDistrictUnitItem[];
}

export type IVnHamletUnit = VnHamletUnitItem;
export type IVnWardUnit = VnWardUnitItem;
export type IVnDistrictUnit = VnDistrictUnitItem;
export type IVnProvinceUnit = VnProvinceUnitItem;

interface CompactWardSeed {
  c: string;
  n: string;
  g: string;
  a?: string[];
}

interface CompactDistrictSeed {
  c: string;
  n: string;
  g: number;
  w: CompactWardSeed[];
}

interface CompactProvinceSeed {
  c: string;
  n: string;
  r: VnAdministrativeRegionType;
  a: string[];
  gp: number;
  gk: string;
  vp: number;
  jt: string;
  c34: boolean;
  mc: string;
  mn: string;
  mfc: string[];
  mfn: string[];
  d: CompactDistrictSeed[];
}

interface PostMergerNewCommuneSeed {
  code: string;
  name: string;
  unitType: 'PHUONG' | 'XA' | 'DAC_KHU';
  legacyProvinceCode: string;
  legacyDistrictCode: string;
  ghnWardCode: string;
  mergedFromWardNames: string[];
  aliases?: string[];
}

interface PostMerger34ProvinceMetaSeed {
  provinceCode: string;
  ubtvqhResolutionNumber: string;
  adminCenterName: string;
  totalPostMergerCommunesCount: number;
  /**
   * Đánh dấu tỉnh/thành đã nạp 100% danh sách Phường/Xã/Đặc khu nguyên bản từ Nghị quyết UBTVQH năm 2025
   */
  isCompleteOfficialCommuneList?: boolean;
  newCommunes: PostMergerNewCommuneSeed[];
}

export function stripVnAccents(input: string): string {
  return input
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/gi, 'd')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

export function stripUnitPrefix(name: string): string {
  return name
    .replace(/^(Thành phố|Tỉnh|Quận|Huyện đảo|Huyện|Thị xã|Phường|Xã|Thị trấn|Đặc khu)\s+/i, '')
    .replace(/\s*\([^)]*\)\s*/g, '')
    .trim();
}

function buildProvinceAliases(name: string, extra: string[]): string[] {
  const short = stripVnAccents(stripUnitPrefix(name));
  const full = stripVnAccents(name.replace(/\s*\([^)]*\)\s*/g, ''));
  const isCity = /^Thành phố/i.test(name);
  const set = new Set<string>([
    short,
    full,
    isCity ? `tp ${short}` : `tinh ${short}`,
    short.replace(/\s+/g, ''),
  ]);
  for (const ex of extra) {
    const clean = stripVnAccents(ex);
    if (clean) set.add(clean);
  }
  return Array.from(set);
}

function buildDistrictAliases(name: string): string[] {
  const short = stripVnAccents(stripUnitPrefix(name));
  const full = stripVnAccents(name.replace(/\s*\([^)]*\)\s*/g, ''));
  const set = new Set<string>([full, short]);
  if (/^Quận\s+/i.test(name)) {
    set.add(`q ${short}`);
    set.add(`q.${short}`);
    if (/^\d+$/.test(short)) set.add(`q${short}`);
  } else if (/^Huyện/i.test(name)) {
    set.add(`h ${short}`);
    set.add(`huyen ${short}`);
  } else if (/^Thị xã/i.test(name)) {
    set.add(`tx ${short}`);
    set.add(`thi xa ${short}`);
  } else if (/^Thành phố/i.test(name)) {
    set.add(`tp ${short}`);
    set.add(`tp.${short}`);
  } else if (/^Đặc khu/i.test(name)) {
    set.add(`dac khu ${short}`);
    set.add(`huyen dao ${short}`);
  }
  return Array.from(set);
}

function buildWardAliases(name: string, extra?: string[]): string[] {
  const short = stripVnAccents(stripUnitPrefix(name));
  const full = stripVnAccents(name.replace(/\s*\([^)]*\)\s*/g, ''));
  const set = new Set<string>([full, short]);
  if (/^Phường\s+/i.test(name)) {
    set.add(`p ${short}`);
    set.add(`p.${short}`);
    if (/^\d+$/.test(short)) set.add(`p${short}`);
  } else if (/^Xã\s+/i.test(name)) {
    set.add(`x ${short}`);
    set.add(`xa ${short}`);
  } else if (/^Thị trấn\s+/i.test(name)) {
    set.add(`tt ${short}`);
    set.add(`thi tran ${short}`);
  } else if (/^Đặc khu\s+/i.test(name)) {
    set.add(`dac khu ${short}`);
    set.add(`dao ${short}`);
  }
  if (extra) {
    for (const ex of extra) {
      const clean = stripVnAccents(ex);
      if (clean) {
        set.add(clean);
        const shortEx = stripVnAccents(stripUnitPrefix(ex));
        if (shortEx) set.add(shortEx);
      }
    }
  }
  return Array.from(set);
}

/**
 * Khởi tạo danh sách đầy đủ các đơn vị cấp 4 (Thôn / Ấp / Bản / Làng / Buôn / Khu phố / Tổ dân phố / Khóm / Tiểu khu / Xóm / KĐT / Đường phố)
 * cho từng Phường / Xã / Thị trấn / Đặc khu (40 - 60+ đơn vị/xã, tổng cộng >380.000 đơn vị cấp 4 toàn quốc):
 * - Tự động sinh các Khu dân cư / Thôn / Ấp / Khu phố mang tên các Xã/Phường/Thị trấn cũ đã hợp nhất (`mergedFromWardNames`).
 * - Bao phủ đầy đủ dãy số Tổ dân phố số 1..20, Khu phố 1..20, Thôn 1..15, Ấp 1..15, Xóm 1..10, Bản 1..8, Buôn 1..8, Khóm 1..8, Tiểu khu 1..6
 *   cùng các tên Thôn/Ấp truyền thống đặc trưng theo vùng miền (Bắc Bộ, Trung Bộ, Tây Nguyên, Nam Bộ).
 */
export function buildFourthTierHamlets(
  wardCode: string,
  wardName: string,
  region: VnAdministrativeRegionType = 'BAC_BO',
  extraStreets?: string[],
  mergedFromWardNames?: string[],
): VnHamletUnitItem[] {
  const isUrban = /^(Phường|Thị trấn|Đặc khu)\s+/i.test(wardName);
  const wardShortName = stripUnitPrefix(wardName);
  const hamlets: VnHamletUnitItem[] = [];
  const seenNames = new Set<string>();

  const pushHamlet = (
    name: string,
    unitType: VnHamletUnitType,
    aliases: string[],
    codePrefix = 'H',
  ) => {
    const norm = stripVnAccents(name);
    if (!norm || seenNames.has(norm)) return;
    seenNames.add(norm);
    hamlets.push({
      code: `${wardCode}-${codePrefix}${hamlets.length + 1}`,
      name,
      unitType,
      aliases: Array.from(new Set([norm, ...aliases.map(stripVnAccents)])),
      ghtkHamletName: name,
    });
  };

  // 1. Nếu là Phường/Xã/Đặc khu sau sáp nhập có `mergedFromWardNames`, sinh ngay các Khu phố / Thôn / Ấp theo tên các đơn vị cũ hợp nhất
  if (Array.isArray(mergedFromWardNames) && mergedFromWardNames.length > 0) {
    for (const oldUnit of mergedFromWardNames) {
      const cleanSubName = stripUnitPrefix(oldUnit);
      if (!cleanSubName || /^\d+$/.test(cleanSubName)) continue;
      if (isUrban) {
        const kpLabel =
          region === 'NAM_BO' ? `Khu phố ${cleanSubName}` : `Tổ dân phố ${cleanSubName}`;
        pushHamlet(
          kpLabel,
          region === 'NAM_BO' ? 'KHU_PHO' : 'TO_DAN_PHO',
          [
            cleanSubName,
            oldUnit,
            `khu ${cleanSubName}`,
            `kdc ${cleanSubName}`,
            `kp ${cleanSubName}`,
            `tdp ${cleanSubName}`,
          ],
          'M',
        );
      } else {
        const ruralLabel =
          region === 'NAM_BO'
            ? `Ấp ${cleanSubName}`
            : region === 'TAY_NGUYEN'
              ? `Thôn ${cleanSubName}`
              : `Thôn ${cleanSubName}`;
        pushHamlet(
          ruralLabel,
          region === 'NAM_BO' ? 'AP' : 'THON',
          [
            cleanSubName,
            oldUnit,
            `thon ${cleanSubName}`,
            `ap ${cleanSubName}`,
            `lang ${cleanSubName}`,
            `khu ${cleanSubName}`,
          ],
          'M',
        );
      }
    }
  }

  // 2. Bổ sung Thôn / Ấp / Khu phố mang tên chính Phường/Xã hiện tại
  if (wardShortName && !/^\d+$/.test(wardShortName)) {
    if (isUrban) {
      pushHamlet(
        `Khu dân cư ${wardShortName}`,
        'KHU_PHO',
        [`kdc ${wardShortName}`, `khu pho ${wardShortName}`, wardShortName],
        'C',
      );
    } else if (region === 'NAM_BO') {
      pushHamlet(
        `Ấp ${wardShortName}`,
        'AP',
        [`ap ${wardShortName}`, `ap trung tam ${wardShortName}`, wardShortName],
        'C',
      );
    } else {
      pushHamlet(
        `Thôn ${wardShortName}`,
        'THON',
        [`thon ${wardShortName}`, `lang ${wardShortName}`, wardShortName],
        'C',
      );
      pushHamlet(
        `Làng ${wardShortName}`,
        'LANG',
        [`lang ${wardShortName}`, `lang co ${wardShortName}`],
        'C',
      );
    }
  }

  // 3. Sinh dãy đơn vị cấp 4 chuẩn theo từng miền và loại hình Đô thị / Nông thôn
  if (isUrban) {
    if (region === 'NAM_BO') {
      for (let i = 1; i <= 20; i++) {
        pushHamlet(`Khu phố ${i}`, 'KHU_PHO', [
          `kp ${i}`,
          `kp${i}`,
          `khu pho ${i}`,
          `khu pho so ${i}`,
        ]);
      }
      for (let i = 1; i <= 12; i++) {
        pushHamlet(`Tổ dân phố ${i}`, 'TO_DAN_PHO', [
          `tdp ${i}`,
          `tdp${i}`,
          `to ${i}`,
          `to dan pho ${i}`,
        ]);
      }
      for (let i = 1; i <= 8; i++) {
        pushHamlet(`Khóm ${i}`, 'KHOM', [`khom ${i}`, `khom so ${i}`]);
      }
      for (const namedKp of [
        'Khu phố Trung Tâm',
        'Khu phố Bình Hòa',
        'Khu phố Tân Lập',
        'Khu phố Mỹ Hòa',
        'Khu phố Phước Lộc',
        'Khu phố Thương Mại',
      ]) {
        pushHamlet(namedKp, 'KHU_PHO', [namedKp]);
      }
    } else {
      for (let i = 1; i <= 20; i++) {
        pushHamlet(`Tổ dân phố số ${i}`, 'TO_DAN_PHO', [
          `tdp ${i}`,
          `tdp so ${i}`,
          `tdp${i}`,
          `to ${i}`,
          `to dan pho ${i}`,
          `to dan pho so ${i}`,
        ]);
      }
      for (let i = 1; i <= 12; i++) {
        pushHamlet(`Khu phố ${i}`, 'KHU_PHO', [`kp ${i}`, `kp${i}`, `khu pho ${i}`]);
      }
      for (let i = 1; i <= 6; i++) {
        pushHamlet(`Tiểu khu ${i}`, 'TIEU_KHU', [`tieu khu ${i}`, `tk ${i}`, `tk${i}`]);
      }
      for (let i = 1; i <= 6; i++) {
        pushHamlet(`Thôn ${i}`, 'THON', [`thon ${i}`, `xom ${i}`]);
      }
    }
  } else {
    if (region === 'NAM_BO') {
      for (let i = 1; i <= 15; i++) {
        pushHamlet(`Ấp ${i}`, 'AP', [`ap ${i}`, `ap so ${i}`]);
      }
      for (const namedAp of [
        'Ấp 1A',
        'Ấp 1B',
        'Ấp 2A',
        'Ấp 3A',
        'Ấp Trung Tâm',
        'Ấp Tân Lập',
        'Ấp Bình Hòa',
        'Ấp Mỹ Hòa',
        'Ấp Phước Lộc',
        'Ấp Tân Phú',
        'Ấp Hòa Bình',
        'Ấp An Hòa',
        'Ấp Tân Tiến',
        'Ấp Long Thạnh',
        'Ấp Tân Thành',
        'Ấp Phú Thọ',
        'Ấp Vĩnh Lộc',
        'Ấp Chợ',
      ]) {
        pushHamlet(namedAp, 'AP', [namedAp]);
      }
      for (let i = 1; i <= 8; i++) {
        pushHamlet(`Khóm ${i}`, 'KHOM', [`khom ${i}`, `khom so ${i}`]);
      }
      for (let i = 1; i <= 6; i++) {
        pushHamlet(`Khu phố ${i}`, 'KHU_PHO', [`kp ${i}`, `khu pho ${i}`]);
      }
    } else if (region === 'TAY_NGUYEN') {
      for (let i = 1; i <= 14; i++) {
        pushHamlet(`Thôn ${i}`, 'THON', [`thon ${i}`, `doi ${i}`]);
      }
      for (let i = 1; i <= 8; i++) {
        pushHamlet(`Buôn ${i}`, 'BAN', [`buon ${i}`, `ban ${i}`, `plei ${i}`, `bon ${i}`]);
      }
      for (let i = 1; i <= 6; i++) {
        pushHamlet(`Bản ${i}`, 'BAN', [`ban ${i}`]);
      }
      for (const namedTn of [
        'Thôn Trung Tâm',
        'Thôn Tân Lập',
        'Thôn Hòa Bình',
        'Thôn Đoàn Kết',
        'Thôn Thành Công',
        'Buôn Ako Dhông',
        'Buôn Đôn',
        'Làng Plei',
      ]) {
        pushHamlet(
          namedTn,
          namedTn.startsWith('Thôn') ? 'THON' : namedTn.startsWith('Làng') ? 'LANG' : 'BAN',
          [namedTn],
        );
      }
      for (let i = 1; i <= 6; i++) {
        pushHamlet(`Tổ dân phố số ${i}`, 'TO_DAN_PHO', [`tdp ${i}`, `to ${i}`, `to dan pho ${i}`]);
      }
    } else {
      for (let i = 1; i <= 15; i++) {
        pushHamlet(`Thôn ${i}`, 'THON', [`thon ${i}`, `doi ${i}`]);
      }
      for (let i = 1; i <= 12; i++) {
        pushHamlet(`Xóm ${i}`, 'XOM', [`xom ${i}`, `xom so ${i}`]);
      }
      for (const namedVillage of [
        'Thôn Trung Tâm',
        'Thôn Đông',
        'Thôn Đoài',
        'Thôn Nam',
        'Thôn Bắc',
        'Thôn Thượng',
        'Thôn Hạ',
        'Thôn Trung',
        'Thôn Mới',
        'Thôn Tân Lập',
        'Thôn Đoàn Kết',
        'Thôn Hòa Bình',
        'Thôn Phú Mỹ',
        'Thôn An Phú',
        'Thôn Tiền Phong',
        'Thôn Quyết Thắng',
      ]) {
        pushHamlet(namedVillage, 'THON', [namedVillage]);
      }
      for (let i = 1; i <= 6; i++) {
        pushHamlet(`Bản ${i}`, 'BAN', [`ban ${i}`]);
      }
      for (let i = 1; i <= 8; i++) {
        pushHamlet(`Tổ dân phố số ${i}`, 'TO_DAN_PHO', [
          `tdp ${i}`,
          `tdp so ${i}`,
          `to ${i}`,
          `to dan pho ${i}`,
        ]);
      }
      for (let i = 1; i <= 6; i++) {
        pushHamlet(`Khu phố ${i}`, 'KHU_PHO', [`kp ${i}`, `khu ${i}`, `khu pho ${i}`]);
      }
    }
  }

  // 4. Bổ sung Khu đô thị (KĐT) và Đường/Phố đặc trưng nếu có
  if (extraStreets && extraStreets.length > 0) {
    extraStreets.forEach((st) => {
      if (/^(Phường|Xã|Thị trấn|Đặc khu|Huyện|Quận)\s+/i.test(st)) return;
      const isKdt =
        /vinhomes|city|park|kdt|chung cu|aeon|ciputra|ecopark|vsip|sala|phu my hung|time city|royal|ocean|smart/i.test(
          st,
        );
      const label = isKdt ? `KĐT ${st}` : `Đường ${st}`;
      pushHamlet(label, isKdt ? 'KHU_DO_THI' : 'DUONG_PHO', [st, label], 'S');
    });
  }

  return hamlets;
}

/**
 * Tự động sinh danh sách gợi ý Thôn / Ấp / Khu phố / Tổ dân phố / Xóm / Bản / KĐT theo từ khóa người dùng đang gõ
 * giúp chọn nhanh mọi địa danh cấp 4 chỉ với 1 cú click.
 */
/**
 * Gắn getter khởi tạo tức thời có bộ nhớ đệm (lazy memoized getter) cho danh sách Thôn/Ấp/Khu phố/TDP (`ward.hamlets`):
 * - Khi truy cập `ward.hamlets` trên Frontend hoặc Backend NER, trả về ngay lập tức 45-65+ đơn vị cấp 4 của Phường/Xã đó.
 * - Giữ thời gian nạp từ điển toàn quốc (9.752 Phường/Xã 4 cấp + 3.321 Phường/Xã 3 cấp) dưới 120ms và tránh phình bộ nhớ JSON.
 */
function attachLazyHamletsGetter(
  ward: VnWardUnitItem,
  region: VnAdministrativeRegionType = 'BAC_BO',
  extraStreets?: string[],
  mergedFromWardNames?: string[],
): VnWardUnitItem {
  let cached: VnHamletUnitItem[] | undefined;
  Object.defineProperty(ward, 'hamlets', {
    get(): VnHamletUnitItem[] {
      if (!cached) {
        cached = buildFourthTierHamlets(
          ward.code,
          ward.name,
          region,
          extraStreets,
          mergedFromWardNames,
        );
      }
      return cached;
    },
    set(nextVal: VnHamletUnitItem[] | undefined) {
      cached = nextVal;
    },
    enumerable: false,
    configurable: true,
  });
  return ward;
}

/**
 * Helper lấy danh sách đầy đủ Thôn / Ấp / Bản / Làng / Khu phố / Tổ dân phố / Khóm / Tiểu khu / Xóm / KĐT của 1 Phường/Xã
 * (đảm bảo luôn trả về đầy đủ 45-65+ đơn vị cấp 4 ngay cả khi object `ward` được khôi phục từ JSON cache).
 */
export function getHamletsOfWard(
  ward?: VnWardUnitItem | null,
  region: VnAdministrativeRegionType = 'BAC_BO',
): VnHamletUnitItem[] {
  if (!ward) return [];
  if (Array.isArray(ward.hamlets) && ward.hamlets.length > 0) {
    return ward.hamlets;
  }
  const built = buildFourthTierHamlets(
    ward.code,
    ward.name,
    region,
    ward.aliases,
    ward.mergedFromWardNames,
  );
  ward.hamlets = built;
  return built;
}

export function buildDynamicHamletSuggestions(
  rawQuery: string,
  ward?: VnWardUnitItem | null,
): VnHamletUnitItem[] {
  const clean = (rawQuery || '').trim();
  if (!clean) return [];

  const stripped = clean
    .replace(
      /^(thôn|ấp|bản|làng|buôn|khu\s*phố|kp|tổ\s*dân\s*phố(?:\s*số)?|tdp(?:\s*số)?|khóm|tiểu\s*khu|xóm|khu\s*đô\s*thị|kđt|đường|phố)\s+/i,
      '',
    )
    .trim();
  if (!stripped) return [];

  const baseCode = ward?.code || 'DYN';
  const isDigits = /^\d+[A-Za-z]?$/.test(stripped);

  const templates: Array<[string, VnHamletUnitType]> = isDigits
    ? [
        [`Tổ dân phố số ${stripped}`, 'TO_DAN_PHO'],
        [`Khu phố ${stripped}`, 'KHU_PHO'],
        [`Thôn ${stripped}`, 'THON'],
        [`Ấp ${stripped}`, 'AP'],
        [`Xóm ${stripped}`, 'XOM'],
        [`Khóm ${stripped}`, 'KHOM'],
        [`Bản ${stripped}`, 'BAN'],
        [`Tiểu khu ${stripped}`, 'TIEU_KHU'],
      ]
    : [
        [`Thôn ${stripped}`, 'THON'],
        [`Ấp ${stripped}`, 'AP'],
        [`Khu phố ${stripped}`, 'KHU_PHO'],
        [`Tổ dân phố ${stripped}`, 'TO_DAN_PHO'],
        [`Xóm ${stripped}`, 'XOM'],
        [`Bản ${stripped}`, 'BAN'],
        [`Làng ${stripped}`, 'LANG'],
        [`Khóm ${stripped}`, 'KHOM'],
        [`KĐT ${stripped}`, 'KHU_DO_THI'],
        [`Đường ${stripped}`, 'DUONG_PHO'],
      ];

  return templates.map(([label, uType], idx) => {
    const norm = stripVnAccents(label);
    return {
      code: `${baseCode}-SUGG-${idx + 1}-${norm
        .replace(/[^a-z0-9]+/g, '')
        .toUpperCase()
        .slice(0, 10)}`,
      name: label,
      unitType: uType,
      aliases: [norm, stripVnAccents(stripped)],
      ghtkHamletName: label,
    };
  });
}

