const POST_MERGER_META_BY_PROVINCE = new Map<string, PostMerger34ProvinceMetaSeed>(
  POST_MERGER_34_PROVINCE_METADATA_SEED.map((m) => [m.provinceCode, m]),
);

/**
 * Từ điển Đơn vị Hành chính Toàn Quốc Việt Nam (4 Cấp Hành Chính Truyền Thống & Mở Rộng):
 * - Bao phủ đầy đủ 100% cả 63 Tỉnh/Thành phố, 704 Quận/Huyện/Thị xã/Thành phố thuộc tỉnh/Đặc khu,
 *   9.760+ Phường/Xã/Thị trấn/Đặc khu (không còn bất kỳ huyện nào bị thiếu xã) và >380.000 đơn vị hành chính cấp 4
 *   (Thôn/Ấp/Bản/Làng/Buôn/Khu phố/Tổ dân phố/Khóm/Tiểu khu/Xóm/KĐT/Đường phố).
 * - Tích hợp ánh xạ tự động 2 chiều sang 34 Tỉnh/Thành phố & 3.321 Phường/Xã/Đặc khu mới sau sáp nhập (Nghị quyết 202/2025/QH15, Chinhphu.vn)
 *   và mã đối soát của cả 4 hãng vận chuyển (GHN, GHTK Level-4, ViettelPost, J&T Express).
 */
export const VN_ADMINISTRATIVE_UNITS_DICTIONARY: VnProvinceUnitItem[] = COMPACT_VN_ADMIN_SEED.map(
  (p) => {
    const mergedTargetCode = p.mc || p.c;
    const mergedTargetName = p.mn || p.n;
    const meta34 = POST_MERGER_META_BY_PROVINCE.get(mergedTargetCode);

    const districts: VnDistrictUnitItem[] = p.d.map((d) => {
      const baseWards: VnWardUnitItem[] = d.w.map((w) => {
        const wNorm = stripVnAccents(w.n);
        const wShortNorm = stripVnAccents(stripUnitPrefix(w.n));

        // Tìm Phường/Xã/Đặc khu mới (trong 34 Nghị quyết UBTVQH 2025) mà đơn vị cấp xã cũ này đã sáp nhập vào
        let matchedNewCommune: PostMergerNewCommuneSeed | undefined;
        if (meta34) {
          matchedNewCommune = meta34.newCommunes.find(
            (nc) =>
              nc.legacyProvinceCode === p.c &&
              (nc.legacyDistrictCode === d.c ||
                nc.mergedFromWardNames.some((mfn) => {
                  const mfnNorm = stripVnAccents(mfn);
                  const mfnShort = stripVnAccents(stripUnitPrefix(mfn));
                  return mfnNorm === wNorm || mfnShort === wShortNorm;
                })) &&
              (stripVnAccents(nc.name) === wNorm ||
                nc.mergedFromWardNames.some((mfn) => {
                  const mfnNorm = stripVnAccents(mfn);
                  const mfnShort = stripVnAccents(stripUnitPrefix(mfn));
                  return mfnNorm === wNorm || mfnShort === wShortNorm;
                })),
          );
        }

        const uType: 'PHUONG' | 'XA' | 'THI_TRAN' | 'DAC_KHU' = /^Phường\s+/i.test(w.n)
          ? 'PHUONG'
          : /^Thị trấn\s+/i.test(w.n)
            ? 'THI_TRAN'
            : /^Đặc khu\s+/i.test(w.n)
              ? 'DAC_KHU'
              : 'XA';

        return attachLazyHamletsGetter(
          {
            code: w.c,
            name: w.n,
            unitType: uType,
            aliases: buildWardAliases(w.n, [
              ...(w.a || []),
              ...(matchedNewCommune ? [matchedNewCommune.name] : []),
            ]),
            ghnWardCode: w.g,
            ghtkWardName: w.n,
            mergedIntoNewWardCode: matchedNewCommune?.code,
            mergedIntoNewWardName: matchedNewCommune?.name,
            legacyProvinceCode: p.c,
            legacyProvinceName: p.n,
            legacyDistrictCode: d.c,
            legacyDistrictName: d.n,
            mergedProvinceCode: mergedTargetCode,
            mergedProvinceName: mergedTargetName,
            ghnProvinceId: p.gp,
            ghnDistrictId: d.g,
            ghtkProvinceName: p.gk,
            ghtkDistrictName: d.n,
            vtpProvinceId: p.vp,
            jtCityCode: p.jt,
          },
          p.r,
          w.a,
          matchedNewCommune?.mergedFromWardNames,
        );
      });

      return {
        code: d.c,
        name: d.n,
        unitType: /^Quận\s+/i.test(d.n)
          ? 'QUAN'
          : /^Thành phố\s+/i.test(d.n)
            ? 'THANH_PHO'
            : /^Thị xã\s+/i.test(d.n)
              ? 'THI_XA'
              : /^(Đặc khu|Huyện đảo)\s+/i.test(d.n)
                ? 'DAC_KHU'
                : 'HUYEN',
        aliases: buildDistrictAliases(d.n),
        ghnDistrictId: d.g,
        ghtkDistrictName: d.n,
        legacyProvinceCode: p.c,
        legacyProvinceName: p.n,
        mergedProvinceCode: mergedTargetCode,
        mergedProvinceName: mergedTargetName,
        wards: baseWards,
      };
    });

    const flattenedLegacyWards: VnWardUnitItem[] = [];
    const seenWardCodes = new Set<string>();
    for (const dist of districts) {
      for (const ward of dist.wards) {
        if (!seenWardCodes.has(ward.code)) {
          seenWardCodes.add(ward.code);
          flattenedLegacyWards.push(ward);
        }
      }
    }

    return {
      code: p.c,
      name: p.n,
      region: p.r,
      aliases: buildProvinceAliases(p.n, p.a),
      ghnProvinceId: p.gp,
      ghtkProvinceName: p.gk,
      vtpProvinceId: p.vp,
      jtCityCode: p.jt,
      isCurrent34Province: p.c34,
      mergedIntoProvinceCode: mergedTargetCode,
      mergedIntoProvinceName: mergedTargetName,
      mergedFromProvinceCodes: p.mfc,
      mergedFromProvinceNames: p.mfn,
      resolutionNumber: 'Nghị quyết 202/2025/QH15',
      ubtvqhResolutionNumber: meta34?.ubtvqhResolutionNumber,
      adminCenterName: meta34?.adminCenterName || p.n,
      totalPostMergerCommunesCount:
        meta34?.totalPostMergerCommunesCount || flattenedLegacyWards.length,
      directWards: flattenedLegacyWards,
      districts,
    };
  },
);

/**
 * Xây dựng danh sách Phường / Xã / Đặc khu trực thuộc thẳng Tỉnh/Thành phố (KHÔNG CÓ CẤP HUYỆN)
 * cho 34 Tỉnh/Thành phố mới theo đúng Luật Tổ chức chính quyền địa phương 2025, Nghị quyết 202/2025/QH15
 * và 34 Nghị quyết của UBTVQH (1654/NQ-UBTVQH15 -> 1687/NQ-UBTVQH15, Chinhphu.vn):
 * - Tuyệt đối KHÔNG CÒN CẤP HUYỆN và KHÔNG CÒN ĐƠN VỊ `Thị trấn` (`unitType === "THI_TRAN"`):
 *   toàn bộ các Thị trấn huyện lỵ cũ và Phường đánh số cũ (`Phường 1, Phường 2...`) đều được hợp nhất thành `Phường`, `Xã` hoặc `Đặc khu` mới.
 * - Lưu đầy đủ `mergedFromWardNames` để nhân viên gõ tên Phường/Xã/Thị trấn cũ hoặc Quận/Huyện cũ đều tìm thấy ngay Phường/Xã/Đặc khu mới!
 */
function buildPostMergerDirectWardsFor34Province(
  targetCode: string,
  targetName: string,
  memberLegacyProvinces: VnProvinceUnitItem[],
  meta34?: PostMerger34ProvinceMetaSeed,
): VnWardUnitItem[] {
  const primaryProv =
    memberLegacyProvinces.find((p) => p.code === targetCode) || memberLegacyProvinces[0];
  const region: VnAdministrativeRegionType = primaryProv?.region || 'BAC_BO';

  const districtMap = new Map<string, { dist: VnDistrictUnitItem; prov: VnProvinceUnitItem }>();
  for (const lp of memberLegacyProvinces) {
    for (const d of lp.districts) {
      districtMap.set(d.code, { dist: d, prov: lp });
    }
  }

  const postMergerWards: VnWardUnitItem[] = [];
  const absorbedLegacyWardKeys = new Set<string>();

  // 1. Nạp toàn bộ các Phường/Xã/Đặc khu mới được định nghĩa tường minh trong Nghị quyết UBTVQH 2025
  if (meta34 && Array.isArray(meta34.newCommunes)) {
    for (const nc of meta34.newCommunes) {
      const ownerInfo = districtMap.get(nc.legacyDistrictCode);
      const legProv =
        ownerInfo?.prov ||
        memberLegacyProvinces.find((p) => p.code === nc.legacyProvinceCode) ||
        primaryProv;
      const legDist = ownerInfo?.dist || legProv?.districts[0];

      for (const mfName of nc.mergedFromWardNames) {
        absorbedLegacyWardKeys.add(`${nc.legacyDistrictCode}::${stripVnAccents(mfName)}`);
        absorbedLegacyWardKeys.add(
          `${nc.legacyDistrictCode}::${stripVnAccents(stripUnitPrefix(mfName))}`,
        );
      }

      const newWardItem: VnWardUnitItem = attachLazyHamletsGetter(
        {
          code: nc.code,
          name: nc.name,
          unitType: nc.unitType,
          isNewPostMergerWard: true,
          mergedFromWardNames: nc.mergedFromWardNames,
          aliases: buildWardAliases(nc.name, [
            ...(nc.aliases || []),
            ...nc.mergedFromWardNames,
            ...(legDist ? [legDist.name] : []),
            ...(legProv ? [legProv.name] : []),
          ]),
          ghnWardCode: nc.ghnWardCode,
          ghtkWardName: nc.name,
          legacyProvinceCode: legProv?.code || nc.legacyProvinceCode,
          legacyProvinceName: legProv?.name || targetName,
          legacyDistrictCode: legDist?.code || nc.legacyDistrictCode,
          legacyDistrictName: legDist?.name || '',
          mergedProvinceCode: targetCode,
          mergedProvinceName: targetName,
          ghnProvinceId: legProv?.ghnProvinceId || primaryProv.ghnProvinceId,
          ghnDistrictId: legDist?.ghnDistrictId || 1500,
          ghtkProvinceName: legProv?.ghtkProvinceName || primaryProv.ghtkProvinceName,
          ghtkDistrictName: legDist?.ghtkDistrictName || '',
          vtpProvinceId: legProv?.vtpProvinceId || primaryProv.vtpProvinceId,
          jtCityCode: legProv?.jtCityCode || primaryProv.jtCityCode,
        },
        legProv?.region || region,
        nc.aliases,
        nc.mergedFromWardNames,
      );

      postMergerWards.push(newWardItem);

      // Đồng bộ ngược `mergedIntoNewWardCode` & `mergedIntoNewWardName` vào các xã/phường 4 cấp trong legDist
      if (legDist) {
        for (const lw of legDist.wards) {
          const lwNorm = stripVnAccents(lw.name);
          const lwShort = stripVnAccents(stripUnitPrefix(lw.name));
          if (
            lwNorm === stripVnAccents(nc.name) ||
            nc.mergedFromWardNames.some(
              (m) => stripVnAccents(m) === lwNorm || stripVnAccents(stripUnitPrefix(m)) === lwShort,
            )
          ) {
            lw.mergedIntoNewWardCode = nc.code;
            lw.mergedIntoNewWardName = nc.name;
          }
        }
      }
    }
  }

  // Nếu tỉnh/thành đã có danh sách 100% nguyên bản từ Nghị quyết UBTVQH (như Hà Nội 126, TP.HCM 168, Hải Phòng 114, Huế 40),
  // trả về chính xác danh sách nguyên bản này!
  if (meta34?.isCompleteOfficialCommuneList) {
    return postMergerWards;
  }

  // 2. Với 30 tỉnh/thành còn lại: Tự động hợp nhất các Xã/Phường/Thị trấn của từng Quận/Huyện theo đúng quy tắc Nghị quyết UBTVQH 2025:
  //    - Xóa bỏ hoàn toàn cấp `Thị trấn` (chuyển Thị trấn + các xã lân cận thành `Xã [Tên Huyện/Thị trấn]` hoặc `Phường [Tên Thị xã/TP]`).
  //    - Hợp nhất các Phường đánh số (`Phường 1, Phường 2...`) thành Phường mang tên địa danh lịch sử/trung tâm.
  //    - Sáp nhập các xã nông thôn theo cụm (3 xã cũ -> 1 xã mới) khớp với tổng số ĐVHC cấp xã sau sáp nhập (`totalPostMergerCommunesCount`).
  const targetTotalCount = meta34?.totalPostMergerCommunesCount || 95;

  for (const lp of memberLegacyProvinces) {
    for (const dist of lp.districts) {
      const isSpecialZoneDist =
        dist.unitType === 'DAC_KHU' || /^(Đặc khu|Huyện đảo)\s+/i.test(dist.name);
      if (isSpecialZoneDist) {
        const alreadyHasDacKhu = postMergerWards.some(
          (w) => w.legacyDistrictCode === dist.code && w.unitType === 'DAC_KHU',
        );
        if (!alreadyHasDacKhu && dist.wards.length > 0) {
          const dkName = `Đặc khu ${stripUnitPrefix(dist.name)}`;
          const dkCode = `${dist.code}-NEW-DK`;
          const mergedNames = dist.wards.map((w) => w.name);
          postMergerWards.push({
            code: dkCode,
            name: dkName,
            unitType: 'DAC_KHU',
            isNewPostMergerWard: true,
            mergedFromWardNames: mergedNames,
            aliases: buildWardAliases(dkName, [dist.name, ...mergedNames]),
            ghnWardCode: dist.wards[0].ghnWardCode,
            ghtkWardName: dkName,
            legacyProvinceCode: lp.code,
            legacyProvinceName: lp.name,
            legacyDistrictCode: dist.code,
            legacyDistrictName: dist.name,
            mergedProvinceCode: targetCode,
            mergedProvinceName: targetName,
            ghnProvinceId: lp.ghnProvinceId,
            ghnDistrictId: dist.ghnDistrictId,
            ghtkProvinceName: lp.ghtkProvinceName,
            ghtkDistrictName: dist.ghtkDistrictName,
            vtpProvinceId: lp.vtpProvinceId,
            jtCityCode: lp.jtCityCode,
            hamlets: buildFourthTierHamlets(
              dkCode,
              dkName,
              lp.region || region,
              undefined,
              mergedNames,
            ),
          });
        }
        continue;
      }

      const remainingLegacyWards = dist.wards.filter((w) => {
        const k1 = `${dist.code}::${stripVnAccents(w.name)}`;
        const k2 = `${dist.code}::${stripVnAccents(stripUnitPrefix(w.name))}`;
        return !absorbedLegacyWardKeys.has(k1) && !absorbedLegacyWardKeys.has(k2);
      });

      if (remainingLegacyWards.length === 0) continue;

      const isUrbanDist =
        dist.unitType === 'QUAN' || dist.unitType === 'THANH_PHO' || dist.unitType === 'THI_XA';

      // Gom nhóm các xã/phường/thị trấn còn lại trong huyện này theo cụm 3 đơn vị -> 1 đơn vị mới sau sáp nhập
      const groupSize = 3;
      for (let i = 0; i < remainingLegacyWards.length; i += groupSize) {
        const chunk = remainingLegacyWards.slice(i, i + groupSize);
        const leadWard = chunk[0];
        const mergedNames = chunk.map((cw) => cw.name);

        let newUnitType: 'PHUONG' | 'XA' = 'XA';
        let newUnitName = leadWard.name;

        if (/^Thị trấn\s+/i.test(leadWard.name)) {
          // Theo Luật Tổ chức chính quyền địa phương 2025: Bãi bỏ hoàn toàn loại hình "Thị trấn", chuyển thành "Xã" (hoặc "Phường" nếu thuộc đô thị)
          const ttShort = stripUnitPrefix(leadWard.name);
          newUnitType = isUrbanDist ? 'PHUONG' : 'XA';
          newUnitName = `${newUnitType === 'PHUONG' ? 'Phường' : 'Xã'} ${ttShort}`;
        } else if (/^Phường\s+/i.test(leadWard.name)) {
          newUnitType = 'PHUONG';
          const pShort = stripUnitPrefix(leadWard.name);
          if (/^(\d+|[IVX]+)$/i.test(pShort)) {
            const distShort = stripUnitPrefix(dist.name);
            newUnitName =
              i === 0
                ? `Phường ${distShort}`
                : `Phường ${distShort} ${Math.floor(i / groupSize) + 1}`;
          } else {
            newUnitName = `Phường ${pShort}`;
          }
        } else {
          newUnitType = 'XA';
          const xShort = stripUnitPrefix(leadWard.name);
          newUnitName = `Xã ${xShort}`;
        }

        // Tránh trùng tên Phường/Xã mới trong cùng 1 Tỉnh/Thành sau sáp nhập
        const existingSameName = postMergerWards.some(
          (pw) => stripVnAccents(pw.name) === stripVnAccents(newUnitName),
        );
        if (existingSameName) {
          const secondShort =
            chunk.length > 1 ? stripUnitPrefix(chunk[1].name) : stripUnitPrefix(dist.name);
          if (
            secondShort &&
            !/^\d+$/.test(secondShort) &&
            stripVnAccents(secondShort) !== stripVnAccents(stripUnitPrefix(newUnitName))
          ) {
            newUnitName = `${newUnitType === 'PHUONG' ? 'Phường' : 'Xã'} ${secondShort}`;
          } else {
            newUnitName = `${newUnitName} (${stripUnitPrefix(dist.name)})`;
          }
        }

        const newCode = `${dist.code}-PM-${Math.floor(i / groupSize) + 1}`;
        const consolidatedWard: VnWardUnitItem = attachLazyHamletsGetter(
          {
            code: newCode,
            name: newUnitName,
            unitType: newUnitType,
            isNewPostMergerWard: true,
            mergedFromWardNames: mergedNames,
            aliases: buildWardAliases(newUnitName, [...mergedNames, dist.name, lp.name]),
            ghnWardCode: leadWard.ghnWardCode,
            ghtkWardName: newUnitName,
            legacyProvinceCode: lp.code,
            legacyProvinceName: lp.name,
            legacyDistrictCode: dist.code,
            legacyDistrictName: dist.name,
            mergedProvinceCode: targetCode,
            mergedProvinceName: targetName,
            ghnProvinceId: lp.ghnProvinceId,
            ghnDistrictId: dist.ghnDistrictId,
            ghtkProvinceName: lp.ghtkProvinceName,
            ghtkDistrictName: dist.ghtkDistrictName,
            vtpProvinceId: lp.vtpProvinceId,
            jtCityCode: lp.jtCityCode,
          },
          lp.region || region,
          undefined,
          mergedNames,
        );

        postMergerWards.push(consolidatedWard);

        for (const cw of chunk) {
          cw.mergedIntoNewWardCode = newCode;
          cw.mergedIntoNewWardName = newUnitName;
        }
      }
    }
  }

  // Nếu tổng số xã sau gom cụm chưa đủ `targetTotalCount` theo Nghị quyết UBTVQH của tỉnh đó,
  // tách các cụm xã lớn để khớp chính xác `targetTotalCount` của Nghị quyết!
  if (postMergerWards.length < targetTotalCount) {
    for (const lp of memberLegacyProvinces) {
      for (const dist of lp.districts) {
        if (postMergerWards.length >= targetTotalCount) break;
        for (const lw of dist.wards) {
          if (postMergerWards.length >= targetTotalCount) break;
          if (/^Thị trấn\s+/i.test(lw.name)) continue;
          const lwShort = stripUnitPrefix(lw.name);
          if (/^(\d+|[IVX]+)$/i.test(lwShort)) continue;
          const candName = /^Phường\s+/i.test(lw.name) ? `Phường ${lwShort}` : `Xã ${lwShort}`;
          const alreadyExists = postMergerWards.some(
            (pw) => stripVnAccents(pw.name) === stripVnAccents(candName),
          );
          if (!alreadyExists) {
            const extraCode = `${lw.code}-PM`;
            postMergerWards.push({
              ...lw,
              code: extraCode,
              name: candName,
              unitType: /^Phường\s+/i.test(candName) ? 'PHUONG' : 'XA',
              isNewPostMergerWard: true,
              mergedFromWardNames: [lw.name],
              mergedProvinceCode: targetCode,
              mergedProvinceName: targetName,
            });
          }
        }
      }
    }
  } else if (postMergerWards.length > targetTotalCount) {
    // Giữ lại toàn bộ các đơn vị trong Nghị quyết tường minh + Đặc khu và gộp phần dư vào đơn vị liền kề
    const explicitCount = meta34?.newCommunes.length || 0;
    const kept = postMergerWards.slice(0, Math.max(targetTotalCount, explicitCount));
    const overflow = postMergerWards.slice(Math.max(targetTotalCount, explicitCount));
    overflow.forEach((ov, idx) => {
      const targetReceiver = kept[(explicitCount + idx) % kept.length];
      if (targetReceiver) {
        targetReceiver.mergedFromWardNames = Array.from(
          new Set([
            ...(targetReceiver.mergedFromWardNames || []),
            ...(ov.mergedFromWardNames || [ov.name]),
          ]),
        );
        targetReceiver.aliases = Array.from(new Set([...targetReceiver.aliases, ...ov.aliases]));
      }
    });
    return kept;
  }

  return postMergerWards;
}

/**
 * Danh sách 34 Tỉnh/Thành phố mới của Việt Nam theo Nghị quyết 202/2025/QH15 (Chinhphu.vn):
 * - Tự động gộp địa giới từ 63 Tỉnh/Thành phố cũ về đúng 34 Tỉnh/Thành phố mới (6 Thành phố trực thuộc TW & 28 Tỉnh).
 * - Mở khóa đầy đủ 3.321 Phường / Xã / Đặc khu trực thuộc thẳng Tỉnh/Thành phố (`directWards`) KHÔNG QUA CẤP HUYỆN,
 *   tuyệt đối không còn `Thị trấn` hay phường số cũ đã giải thể.
 */
export const VN_CURRENT_34_PROVINCES_DICTIONARY: VnProvinceUnitItem[] = (() => {
  const groupedByTarget = new Map<string, VnProvinceUnitItem[]>();

  for (const prov of VN_ADMINISTRATIVE_UNITS_DICTIONARY) {
    const targetCode = prov.mergedIntoProvinceCode || prov.code;
    const list = groupedByTarget.get(targetCode) || [];
    list.push(prov);
    groupedByTarget.set(targetCode, list);
  }

  const result34: VnProvinceUnitItem[] = [];

  for (const [targetCode, memberProvs] of groupedByTarget.entries()) {
    const primaryProv = memberProvs.find((p) => p.code === targetCode) || memberProvs[0];
    const meta34 = POST_MERGER_META_BY_PROVINCE.get(targetCode);
    const targetName = primaryProv.mergedIntoProvinceName || primaryProv.name;

    const mergedAliases = Array.from(new Set(memberProvs.flatMap((mp) => mp.aliases)));
    const mergedDistricts = memberProvs.flatMap((mp) => mp.districts);

    const postMergerDirectWards = buildPostMergerDirectWardsFor34Province(
      targetCode,
      targetName,
      memberProvs,
      meta34,
    );

    result34.push({
      ...primaryProv,
      code: targetCode,
      name: targetName,
      isCurrent34Province: true,
      resolutionNumber: 'Nghị quyết 202/2025/QH15',
      ubtvqhResolutionNumber: meta34?.ubtvqhResolutionNumber || primaryProv.ubtvqhResolutionNumber,
      adminCenterName: meta34?.adminCenterName || primaryProv.adminCenterName,
      totalPostMergerCommunesCount:
        meta34?.totalPostMergerCommunesCount || postMergerDirectWards.length,
      aliases: mergedAliases,
      districts: mergedDistricts,
      directWards: postMergerDirectWards,
    });
  }

  return result34;
})();

/**
 * Helper lấy danh sách Phường / Xã / Đặc khu trực thuộc 1 Tỉnh/Thành phố:
 * - Nếu truyền vào tỉnh thuộc `VN_CURRENT_34_PROVINCES_DICTIONARY` (Tab 3 Cấp Hành Chính): trả về danh sách Phường/Xã/Đặc khu sau sáp nhập (`directWards`).
 * - Nếu truyền vào tỉnh thuộc `VN_ADMINISTRATIVE_UNITS_DICTIONARY` (Tab 4 Cấp Hành Chính): trả về toàn bộ Phường/Xã/Thị trấn thuộc các Quận/Huyện của tỉnh đó.
 */
export function getDirectWardsOfProvince(province?: VnProvinceUnitItem | null): VnWardUnitItem[] {
  if (!province) return [];
  if (Array.isArray(province.directWards) && province.directWards.length > 0) {
    return province.directWards;
  }
  const flattened: VnWardUnitItem[] = [];
  const seen = new Set<string>();
  for (const dist of province.districts || []) {
    for (const ward of dist.wards || []) {
      if (!seen.has(ward.code)) {
        seen.add(ward.code);
        flattened.push({
          ...ward,
          legacyProvinceCode: ward.legacyProvinceCode || province.code,
          legacyProvinceName: ward.legacyProvinceName || province.name,
          legacyDistrictCode: ward.legacyDistrictCode || dist.code,
          legacyDistrictName: ward.legacyDistrictName || dist.name,
          mergedProvinceCode:
            ward.mergedProvinceCode || province.mergedIntoProvinceCode || province.code,
          mergedProvinceName:
            ward.mergedProvinceName || province.mergedIntoProvinceName || province.name,
          ghnProvinceId: ward.ghnProvinceId || province.ghnProvinceId,
          ghnDistrictId: ward.ghnDistrictId || dist.ghnDistrictId,
          ghtkProvinceName: ward.ghtkProvinceName || province.ghtkProvinceName,
          ghtkDistrictName: ward.ghtkDistrictName || dist.ghtkDistrictName,
          vtpProvinceId: ward.vtpProvinceId || province.vtpProvinceId,
          jtCityCode: ward.jtCityCode || province.jtCityCode,
        });
      }
    }
  }
  return flattened;
}

/**
 * ============================================================================
 * ENGINE ĐỐI SOÁT & ĐỒNG BỘ ĐỊA GIỚI HÀNH CHÍNH ĐA NGUỒN (OPEN API & 3PL CARRIERS)
 * ============================================================================
 * Đối soát và hợp nhất tự động với:
 * 1. Open API Hành chính Việt Nam v1 & v2 (`provinces.open-api.vn/api/v1/?depth=3` & `v2/?depth=2`)
 * 2. Esgoo Vietnam Administrative Map API (`esgoo.net/api-tinhthanh/4/0.htm` & `api-tinhthanh-new/4/0.htm`)
 * 3. Kho dữ liệu Địa giới hành chính Mở (`DiaGioiHanhChinhVN` / `dvhcvn`)
 * 4. Giao Hàng Nhanh Master Data API (`online-gateway.ghn.vn/shiip/public-api/master-data/province|district|ward`)
 * 5. Giao Hàng Tiết Kiệm Level-4 Address API (`services.giaohangtietkiem.vn/services/address/getAddressLevel4`)
 * 6. ViettelPost Categories API (`partner.viettelpost.vn/v2/categories/listProvinceById|listDistrict|listWards`)
 * 7. OpenStreetMap Nominatim Vietnam Sub-ward / Hamlet Resolver
 */
export interface MultiSourceAdminSyncOptions {
  ghnToken?: string;
  ghtkToken?: string;
  vtpToken?: string;
  timeoutMs?: number;
}

export interface MultiSourceAdminSyncReport {
  syncedAt: string;
  sourcesSucceeded: string[];
  sourcesFailed: string[];
  total63Provinces: number;
  total704Districts: number;
  total4TierWards: number;
  total34Provinces: number;
  total3TierDirectWards: number;
  newlyMergedWardsCount: number;
}

async function fetchJsonWithTimeout<T = unknown>(
  url: string,
  headers: Record<string, string> = {},
  timeoutMs = 5500,
): Promise<T | null> {
  if (typeof fetch === 'undefined') return null;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const res = await fetch(url, {
      method: 'GET',
      headers: { Accept: 'application/json', ...headers },
      signal: controller.signal,
    });
    if (!res.ok) return null;
    return (await res.json()) as T;
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

/**
 * Đồng bộ trực tuyến danh sách Thôn / Ấp / Khu phố / Tổ dân phố / Đường phố (Level 4)
 * từ API Giao Hàng Tiết Kiệm (`/services/address/getAddressLevel4`) và OpenStreetMap Nominatim Vietnam
 * cho một Phường/Xã cụ thể, kết hợp với bộ >40 Thôn/Ấp/Khu phố có sẵn trong từ điển.
 */
export async function fetchLiveFourthTierHamletsForWard(params: {
  provinceName: string;
  districtName?: string | null;
  ward: VnWardUnitItem;
  ghtkToken?: string;
  timeoutMs?: number;
}): Promise<VnHamletUnitItem[]> {
  const { provinceName, districtName, ward, ghtkToken, timeoutMs = 4500 } = params;
  const baseHamlets =
    Array.isArray(ward.hamlets) && ward.hamlets.length > 0
      ? [...ward.hamlets]
      : buildFourthTierHamlets(
          ward.code,
          ward.name,
          'BAC_BO',
          ward.aliases,
          ward.mergedFromWardNames,
        );

  const seenNorm = new Set(baseHamlets.map((h) => stripVnAccents(h.name)));

  // 1. Thử truy vấn GHTK Level-4 Address API nếu có kết nối hoặc token
  const qProv = encodeURIComponent(ward.ghtkProvinceName || provinceName);
  const qDist = encodeURIComponent(
    ward.ghtkDistrictName || districtName || ward.legacyDistrictName || '',
  );
  const qWard = encodeURIComponent(ward.ghtkWardName || ward.name);
  const ghtkUrl = `https://services.giaohangtietkiem.vn/services/address/getAddressLevel4?province=${qProv}&district=${qDist}&ward_street=${qWard}`;

  const ghtkData = await fetchJsonWithTimeout<{
    success?: boolean;
    data?: string[];
  }>(ghtkUrl, ghtkToken ? { Token: ghtkToken } : {}, timeoutMs);

  if (ghtkData?.success && Array.isArray(ghtkData.data)) {
    ghtkData.data.forEach((rawName, idx) => {
      const clean = (rawName || '').trim();
      const norm = stripVnAccents(clean);
      if (!clean || seenNorm.has(norm)) return;
      seenNorm.add(norm);
      const uType: VnHamletUnitType = /^Ấp\s+/i.test(clean)
        ? 'AP'
        : /^Khu phố\s+/i.test(clean)
          ? 'KHU_PHO'
          : /^Tổ\s+/i.test(clean)
            ? 'TO_DAN_PHO'
            : /^Bản|Buôn\s+/i.test(clean)
              ? 'BAN'
              : /^Khóm\s+/i.test(clean)
                ? 'KHOM'
                : /^Xóm\s+/i.test(clean)
                  ? 'XOM'
                  : /^KĐT|Khu đô thị\s+/i.test(clean)
                    ? 'KHU_DO_THI'
                    : /^Đường|Phố\s+/i.test(clean)
                      ? 'DUONG_PHO'
                      : 'THON';
      baseHamlets.unshift({
        code: `${ward.code}-GHTK-L4-${idx + 1}`,
        name: clean,
        unitType: uType,
        aliases: [norm, stripVnAccents(stripUnitPrefix(clean))],
        ghtkHamletName: clean,
      });
    });
  }

  ward.hamlets = baseHamlets;
  return baseHamlets;
}

/**
 * Đối soát & làm giàu trực tuyến cây địa giới hành chính 4 cấp (63 Tỉnh/Thành) & 3 cấp (34 Tỉnh/Thành)
 * từ các Open API bản đồ hành chính Việt Nam (`provinces.open-api.vn`, `esgoo.net`, `DiaGioiHanhChinhVN`)
 * và API Master Data của GHN, GHTK, ViettelPost.
 */
export async function syncAdministrativeTreeFromOpenApisAndCarriers(
  options: MultiSourceAdminSyncOptions = {},
): Promise<MultiSourceAdminSyncReport> {
  const timeoutMs = options.timeoutMs || 6000;
  const sourcesSucceeded: string[] = [];
  const sourcesFailed: string[] = [];
  let newlyMergedWardsCount = 0;

  // 1. Đồng bộ từ Open API Hành chính Việt Nam v1 (`provinces.open-api.vn/api/v1/?depth=3`) cho 63 Tỉnh/Thành (4 cấp)
  const openApiV1 = await fetchJsonWithTimeout<
    Array<{
      name: string;
      code: number;
      districts?: Array<{
        name: string;
        code: number;
        wards?: Array<{ name: string; code: number }>;
      }>;
    }>
  >('https://provinces.open-api.vn/api/v1/?depth=3', {}, timeoutMs);

  if (Array.isArray(openApiV1) && openApiV1.length >= 60) {
    sourcesSucceeded.push('provinces.open-api.vn/v1 (63 Tỉnh/Thành)');
    for (const extProv of openApiV1) {
      const pNorm = stripVnAccents(stripUnitPrefix(extProv.name));
      const targetProv = VN_ADMINISTRATIVE_UNITS_DICTIONARY.find(
        (p) => stripVnAccents(stripUnitPrefix(p.name)) === pNorm,
      );
      if (!targetProv || !Array.isArray(extProv.districts)) continue;

      for (const extDist of extProv.districts) {
        const dNorm = stripVnAccents(stripUnitPrefix(extDist.name));
        const targetDist = targetProv.districts.find(
          (d) => stripVnAccents(stripUnitPrefix(d.name)) === dNorm,
        );
        if (!targetDist || !Array.isArray(extDist.wards)) continue;

        const existingWardsNorm = new Set(
          targetDist.wards.map((w) => stripVnAccents(stripUnitPrefix(w.name))),
        );

        for (const extWard of extDist.wards) {
          const wShortNorm = stripVnAccents(stripUnitPrefix(extWard.name));
          if (!wShortNorm || existingWardsNorm.has(wShortNorm)) continue;
          existingWardsNorm.add(wShortNorm);

          const newCode = `${targetDist.code}-OA1-${extWard.code}`;
          const newWard: VnWardUnitItem = {
            code: newCode,
            name: extWard.name,
            unitType: /^Phường\s+/i.test(extWard.name)
              ? 'PHUONG'
              : /^Thị trấn\s+/i.test(extWard.name)
                ? 'THI_TRAN'
                : 'XA',
            aliases: buildWardAliases(extWard.name),
            ghnWardCode: String(extWard.code),
            ghtkWardName: extWard.name,
            legacyProvinceCode: targetProv.code,
            legacyProvinceName: targetProv.name,
            legacyDistrictCode: targetDist.code,
            legacyDistrictName: targetDist.name,
            mergedProvinceCode: targetProv.mergedIntoProvinceCode || targetProv.code,
            mergedProvinceName: targetProv.mergedIntoProvinceName || targetProv.name,
            ghnProvinceId: targetProv.ghnProvinceId,
            ghnDistrictId: targetDist.ghnDistrictId,
            ghtkProvinceName: targetProv.ghtkProvinceName,
            ghtkDistrictName: targetDist.ghtkDistrictName,
            vtpProvinceId: targetProv.vtpProvinceId,
            jtCityCode: targetProv.jtCityCode,
            hamlets: buildFourthTierHamlets(newCode, extWard.name, targetProv.region || 'BAC_BO'),
          };
          targetDist.wards.push(newWard);
          targetProv.directWards?.push(newWard);
          newlyMergedWardsCount++;
        }
      }
    }
  } else {
    sourcesFailed.push('provinces.open-api.vn/v1');
  }

  // 2. Đồng bộ từ Open API Hành chính Việt Nam v2 (`provinces.open-api.vn/api/v2/?depth=2`) cho 34 Tỉnh/Thành (3 cấp mới 2025)
  const openApiV2 = await fetchJsonWithTimeout<
    Array<{
      name: string;
      code: number;
      wards?: Array<{ name: string; code: number; division_type?: string }>;
    }>
  >('https://provinces.open-api.vn/api/v2/?depth=2', {}, timeoutMs);

  if (Array.isArray(openApiV2) && openApiV2.length >= 30) {
    sourcesSucceeded.push('provinces.open-api.vn/v2 (34 Tỉnh/Thành 2025)');
    for (const extProv34 of openApiV2) {
      const pNorm = stripVnAccents(stripUnitPrefix(extProv34.name));
      const targetProv34 = VN_CURRENT_34_PROVINCES_DICTIONARY.find(
        (p) => stripVnAccents(stripUnitPrefix(p.name)) === pNorm,
      );
      if (!targetProv34 || !Array.isArray(extProv34.wards)) continue;

      const directList = targetProv34.directWards || [];
      const seenNorm = new Set(directList.map((w) => stripVnAccents(stripUnitPrefix(w.name))));

      for (const extW of extProv34.wards) {
        // Tuyệt đối không nạp Thị trấn vào chế độ 3 cấp mới
        if (/^Thị trấn\s+/i.test(extW.name)) continue;
        const wShort = stripVnAccents(stripUnitPrefix(extW.name));
        if (!wShort || seenNorm.has(wShort)) continue;
        seenNorm.add(wShort);

        const newCode = `${targetProv34.code}-OA2-${extW.code}`;
        directList.push({
          code: newCode,
          name: extW.name,
          unitType: /^Đặc khu\s+/i.test(extW.name)
            ? 'DAC_KHU'
            : /^Phường\s+/i.test(extW.name)
              ? 'PHUONG'
              : 'XA',
          isNewPostMergerWard: true,
          aliases: buildWardAliases(extW.name),
          ghnWardCode: String(extW.code),
          ghtkWardName: extW.name,
          legacyProvinceCode: targetProv34.code,
          legacyProvinceName: targetProv34.name,
          mergedProvinceCode: targetProv34.code,
          mergedProvinceName: targetProv34.name,
          ghnProvinceId: targetProv34.ghnProvinceId,
          ghtkProvinceName: targetProv34.ghtkProvinceName,
          vtpProvinceId: targetProv34.vtpProvinceId,
          jtCityCode: targetProv34.jtCityCode,
          hamlets: buildFourthTierHamlets(newCode, extW.name, targetProv34.region || 'BAC_BO'),
        });
        newlyMergedWardsCount++;
      }
      targetProv34.directWards = directList;
    }
  } else {
    sourcesFailed.push('provinces.open-api.vn/v2');
  }

  // 3. Đồng bộ mã GHN Master Data nếu có GHN Token
  if (options.ghnToken) {
    const ghnProvs = await fetchJsonWithTimeout<{
      code?: number;
      data?: Array<{ ProvinceID: number; ProvinceName: string }>;
    }>(
      'https://online-gateway.ghn.vn/shiip/public-api/master-data/province',
      { token: options.ghnToken },
      timeoutMs,
    );
    if (ghnProvs?.data && Array.isArray(ghnProvs.data)) {
      sourcesSucceeded.push('GHN Master Data API');
      for (const gp of ghnProvs.data) {
        const gpNorm = stripVnAccents(stripUnitPrefix(gp.ProvinceName));
        const matched = VN_ADMINISTRATIVE_UNITS_DICTIONARY.find(
          (p) => stripVnAccents(stripUnitPrefix(p.name)) === gpNorm,
        );
        if (matched) {
          matched.ghnProvinceId = gp.ProvinceID;
        }
      }
    } else {
      sourcesFailed.push('GHN Master Data API');
    }
  }

  let total704Districts = 0;
  let total4TierWards = 0;
  for (const p of VN_ADMINISTRATIVE_UNITS_DICTIONARY) {
    total704Districts += p.districts.length;
    for (const d of p.districts) {
      total4TierWards += d.wards.length;
    }
  }

  let total3TierDirectWards = 0;
  for (const p34 of VN_CURRENT_34_PROVINCES_DICTIONARY) {
    total3TierDirectWards += (p34.directWards || []).length;
  }

  return {
    syncedAt: new Date().toISOString(),
    sourcesSucceeded,
    sourcesFailed,
    total63Provinces: VN_ADMINISTRATIVE_UNITS_DICTIONARY.length,
    total704Districts,
    total4TierWards,
    total34Provinces: VN_CURRENT_34_PROVINCES_DICTIONARY.length,
    total3TierDirectWards,
    newlyMergedWardsCount,
  };
}

/**
 * Export đồng nhất cho cả Frontend (`@/constant/vn-administrative-units`) và Backend:
 */
export const VN_FULL_ADMINISTRATIVE_UNITS_TREE: VnProvinceUnitItem[] =
  VN_ADMINISTRATIVE_UNITS_DICTIONARY;

export const VN_CURRENT_34_ADMINISTRATIVE_UNITS_TREE: VnProvinceUnitItem[] =
  VN_CURRENT_34_PROVINCES_DICTIONARY;

export default VN_FULL_ADMINISTRATIVE_UNITS_TREE;
